            .count();
    queryLog.recordCount(total);
    return total;
}

private static boolean matches(CustomerFilter filter, Customer customer) {
    if (filter == null) {
        return true;
    }
    if (filter.statuses() != null && !filter.statuses().isEmpty()
            && !filter.statuses().contains(customer.status())) {
        return false;
    }
    List<String> terms = nameTerms(filter.name());
    if (terms.isEmpty()) {
        return true;
    }
    String first = fold(customer.firstName());
    String last = fold(customer.lastName());
    for (String term : terms) {
        if (!first.contains(term) && !last.contains(term)) {
            return false;
        }
    }
    return true;
}

private static List<String> nameTerms(String name) {
    if (name == null) {
        return List.of();
    }
    return Arrays.stream(name.trim().split("\\s+"))
            .map(CustomerRepository::fold)
            .filter(term -> !term.isEmpty())
            .toList();
}

/** Case- and accent-folded form of the string, for substring matching. */
private static String fold(String value) {
    if (value == null) {
        return "";
    }
    String withoutMarks = Normalizer.normalize(value, Normalizer.Form.NFD)
            .replaceAll("\\p{M}", "");
    return withoutMarks.toLowerCase(Locale.ROOT);
}
