private static List<CustomerStatus> parseStatuses(String csv) {
    if (csv == null || csv.isBlank()) {
        return List.of();
    }
    List<CustomerStatus> result = new ArrayList<>();
    for (String part : csv.split(",")) {
        String trimmed = part.trim();
        if (trimmed.isEmpty()) {
            continue;
        }
        try {
            result.add(CustomerStatus.valueOf(trimmed));
        } catch (IllegalArgumentException ignored) {
            // unknown status in URL: ignore
        }
    }
    return result;
}
```

