+package com.example.customers.domain;
+
+import java.util.List;
+
+/**
+ * A filter applied to customer queries by {@link CustomerRepository}.
+ *
+ * <p>Both criteria are combined with AND: a customer matches only when it
+ * satisfies the name condition <em>and</em> the status condition.
+ *
+ * @param name     free text, split on whitespace into terms; every term must
+ *                 appear (case- and accent-insensitively) as a substring of the
+ *                 first or last name. Blank matches every customer.
+ * @param statuses when non-empty, only customers with one of these statuses
+ *                 match; empty matches every status
+ */
+public record CustomerFilter(String name, List<CustomerStatus> statuses) {
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name;
+        statuses = (statuses == null) ? List.of() : List.copyOf(statuses);
+    }
+
+    /** A filter that matches every customer. */
+    public static CustomerFilter empty() {
+        return new CustomerFilter("", List.of());
+    }
+
+    /** Whether the filter narrows the data set at all. */
+    public boolean isActive() {
+        return !name.isBlank() || !statuses.isEmpty();
+    }
+}
