+    /**
+     * Whether a customer satisfies both parts of the filter: the name terms and
+     * the set of statuses.
+     */
+    private static boolean matches(CustomerFilter filter, Customer customer) {
+        if (filter == null) {
+            return true;
+        }
+        if (!filter.statuses().isEmpty() && !filter.statuses().contains(customer.status())) {
+            return false;
+        }
+        List<String> terms = nameTerms(filter.name());
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String first = fold(customer.firstName());
+        String last = fold(customer.lastName());
+        for (String term : terms) {
+            if (!first.contains(term) && !last.contains(term)) {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    /** The name filter split into folded, non-blank search terms. */
+    private static List<String> nameTerms(String name) {
+        if (name == null || name.isBlank()) {
+            return List.of();
+        }
+        return Arrays.stream(name.trim().split("\\s+"))
+                .map(CustomerRepository::fold)
+                .filter(term -> !term.isEmpty())
+                .toList();
+    }
+
+    /**
+     * The case- and accent-folded form of a value, so that substring matching
+     * ignores case and diacritics in both the search term and the stored name.
+     */
+    private static String fold(String value) {
+        if (value == null) {
+            return "";
+        }
+        String withoutDiacritics = Normalizer.normalize(value, Normalizer.Form.NFD)
+                .replaceAll("\\p{M}", "");
+        return withoutDiacritics.toLowerCase(Locale.ROOT);
+    }
