+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import com.example.customers.domain.QueryLog;
+
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import org.junit.jupiter.api.AfterEach;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+
+/**
+ * Real-browser (Playwright via Drama Finder) checks for the customer filter.
+ *
+ * <p>These are the two things that can only be observed in a real browser: what
+ * the address bar says while the filter changes, and what typing costs the
+ * backend (measured through the app's own {@link QueryLog}).
+ *
+ * <p>Named {@code *IT} so plain {@code mvn test} (surefire) does not run it; it
+ * is driven in a browser environment with
+ * {@code mvn -o test -Dtest=CustomerListBrowserIT}.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListBrowserIT extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://[REDACTED]host:" + port + "/";
+    }
+
+    @BeforeEach
+    void setUp() throws Exception {
+        super.setupTest();
+    }
+
+    @AfterEach
+    void tearDown() {
+        super.cleanupTest();
+    }
+
+    private Locator nameField() {
+        // The actual editable input is the slotted <input slot="input"> inside
+        // the vaadin-text-field component.
+        return page.locator("vaadin-text-field input").first();
+    }
+
+    private void waitUntilUrlContains(String fragment) {
+        page.waitForFunction("() => location.search.includes('" + fragment + "')", null,
+                new Page.WaitForFunctionOptions().setTimeout(8000));
+    }
+
+    private void waitUntilUrlHasNo(String fragment) {
+        page.waitForFunction("() => !location.search.includes('" + fragment + "')", null,
+                new Page.WaitForFunctionOptions().setTimeout(8000));
+    }
+
+    private void waitUntilSummary(String text) {
+        page.waitForFunction(
+                "() => { const el = document.querySelector('#summary'); return el && el.textContent === '"
+                        + text + "'; }",
+                null, new Page.WaitForFunctionOptions().setTimeout(8000));
+    }
+
+    @Test
+    void theAddressBarCarriesTheNameFilter() {
+        nameField().pressSequentially("aal", new Locator.PressSequentiallyOptions().setDelay(30));
+        waitUntilUrlContains("name=aal");
+
+        assertTrue(page.url().contains("name=aal"), "address bar is " + page.url());
+        assertTrue(!page.url().contains("status="), "no status parameter expected: " + page.url());
+    }
+
+    @Test
+    void anEmptyFilterLeavesNoParametersBehind() {
+        nameField().pressSequentially("aal", new Locator.PressSequentiallyOptions().setDelay(30));
+        waitUntilUrlContains("name=aal");
+
+        nameField().fill("");
+        waitUntilUrlHasNo("name");
+
+        assertTrue(!page.url().contains("name=") && !page.url().contains("status="),
+                "empty filter must not leave parameters: " + page.url());
+    }
+
+    @Test
+    void theUrlAppliesTheFilterWhenThePageOpens() {
+        page.navigate("http://[REDACTED]host:" + port + "/?name=aal&status=ACTIVE");
+        waitUntilSummary("Showing 5 of 500");
+
+        assertEquals("aal", nameField().inputValue());
+        assertEquals("Showing 5 of 500", page.locator("#summary").textContent());
+    }
+
+    @Test
+    void typingAWholeWordCostsFewBackendQueries() {
+        queryLog.clear();
+        String word = "pettersson";
+        nameField().pressSequentially(word, new Locator.PressSequentiallyOptions().setDelay(30));
+        waitUntilSummary("Showing 14 of 500");
+
+        int pageQueries = queryLog.pageQueries().size();
+        assertTrue(pageQueries <= 2,
+                "typing a " + word.length() + "-letter name cost " + pageQueries + " page queries");
+        assertTrue(pageQueries < word.length(),
+                "typing must not query the backend once per keystroke, got " + pageQueries);
+    }
+}
